import sys
P=[]
for l in open("prog.pw9"):
    l=l.split(";")[0].strip()
    if l: P.append(l.split())
R=dict(a=0,b=0,c=0,d=0)
v=lambda x:R[x] if x in R else int(x)
pc=0;n=0;s=0
while 0<=pc<len(P) and n<10**7:
    i=P[pc];op=i[0];n+=1;nx=pc+1
    if op=="set":R[i[1]]=v(i[2])%65536
    elif op=="add":R[i[1]]=(R[i[1]]+v(i[2]))%65536
    elif op=="mul":R[i[1]]=(R[i[1]]*v(i[2]))%65536
    elif op=="mod":
        if v(i[2])>0:R[i[1]]%=v(i[2])
    elif op=="dec":R[i[1]]=max(0,R[i[1]]-1)
    elif op=="jnz":
        if v(i[1])!=0:nx=pc+v(i[2])
    elif op=="skp":
        if v(i[1])<v(i[2]):nx=pc+2
    elif op=="out":s+=v(i[1])
    pc=nx
print(s,n,pc)
